import type { WerseeStoredObject } from '@/services/werseeStorage';

export type CloudSpaceKind = 'personal' | 'team';
export type CloudFileKind = 'image' | 'pdf' | 'video' | 'audio' | 'text' | 'archive' | 'file';
export type CloudView = 'files' | 'recent' | 'starred' | 'shared' | 'trash';

export interface CloudStorageProfile {
  cloud_handle: string;
  plan_key: string;
  personal_quota_bytes: number;
  personal_used_bytes: number;
  personal_remaining_bytes: number;
  stripe_subscription_status: string | null;
}

export interface CloudWorkspace {
  id: string;
  name: string;
  role: 'owner' | 'editor' | 'viewer';
  quota_bytes: number;
  used_bytes: number;
}

export interface CloudFile {
  id: string;
  owner_id: string;
  name: string;
  description: string;
  folder: string;
  storage_path: string;
  mime_type: string;
  file_type: string;
  slug: string;
  size_bytes: number;
  space_kind: CloudSpaceKind;
  workspace_id: string | null;
  storage_object_id: string | null;
  storage_file_id: string | null;
  storage_provider: 'strato' | 'supabase';
  starred: boolean;
  deleted_at: string | null;
  last_opened_at: string | null;
  created_at: string;
  updated_at: string;
}

export const normalizeCloudFile = (row: Record<string, unknown>): CloudFile => ({
  id: String(row.id || ''),
  owner_id: String(row.owner_id || ''),
  name: String(row.name || 'Untitled file'),
  description: String(row.description || ''),
  folder: String(row.folder || 'My files'),
  storage_path: String(row.storage_path || ''),
  mime_type: String(row.mime_type || 'application/octet-stream'),
  file_type: String(row.file_type || 'file'),
  slug: String(row.slug || 'file'),
  size_bytes: Number(row.size_bytes || 0),
  space_kind: row.space_kind === 'team' ? 'team' : 'personal',
  workspace_id: row.workspace_id ? String(row.workspace_id) : null,
  storage_object_id: row.storage_object_id ? String(row.storage_object_id) : null,
  storage_file_id: row.storage_file_id ? String(row.storage_file_id) : null,
  storage_provider: row.storage_provider === 'strato' ? 'strato' : 'supabase',
  starred: Boolean(row.starred),
  deleted_at: row.deleted_at ? String(row.deleted_at) : null,
  last_opened_at: row.last_opened_at ? String(row.last_opened_at) : null,
  created_at: String(row.created_at || new Date(0).toISOString()),
  updated_at: String(row.updated_at || row.created_at || new Date(0).toISOString()),
});

export const formatCloudBytes = (value: number) => {
  if (!Number.isFinite(value) || value <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const unit = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1);
  const amount = value / (1024 ** unit);
  return `${amount >= 10 || unit === 0 ? amount.toFixed(0) : amount.toFixed(1)} ${units[unit]}`;
};

export const cloudSlug = (value: string, fallback = 'file') => value
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 80) || fallback;

export const sanitizeCloudFileName = (value: string) => {
  const cleaned = value.replace(/[\\/:*?"<>|\u0000-\u001f]/g, '-').replace(/\s+/g, ' ').trim();
  return (cleaned || 'untitled-file').slice(0, 255);
};

export const cloudFileKind = (input: Pick<CloudFile, 'mime_type' | 'name' | 'file_type'> | File): CloudFileKind => {
  const mime = 'type' in input ? input.type : input.mime_type;
  const name = input.name.toLowerCase();
  const declared = 'file_type' in input ? input.file_type : '';
  if (declared === 'image' || mime.startsWith('image/')) return 'image';
  if (declared === 'video' || mime.startsWith('video/')) return 'video';
  if (declared === 'audio' || mime.startsWith('audio/')) return 'audio';
  if (declared === 'pdf' || mime === 'application/pdf' || name.endsWith('.pdf')) return 'pdf';
  if (declared === 'text' || mime.startsWith('text/') || /\.(md|txt|json|csv|js|ts|tsx|jsx|css|html|xml|yml|yaml)$/i.test(name)) return 'text';
  if (/\.(zip|rar|7z|tar|gz)$/i.test(name)) return 'archive';
  return 'file';
};

export const buildCloudLogicalPath = ({
  userId,
  workspaceId,
  folder,
  objectId,
  fileName,
}: {
  userId: string;
  workspaceId?: string | null;
  folder: string;
  objectId: string;
  fileName: string;
}) => {
  const root = workspaceId ? `workspaces/${workspaceId}` : `personal/${userId}`;
  return `${root}/${cloudSlug(folder, 'my-files')}/${objectId}-${sanitizeCloudFileName(fileName)}`;
};

export const cloudFileToStoredObject = (file: CloudFile): WerseeStoredObject | null => {
  if (!file.storage_object_id) return null;
  return {
    objectId: file.storage_object_id,
    provider: file.storage_provider,
    bucketId: 'wersee-files',
    logicalPath: file.storage_path,
    fileId: file.storage_file_id,
    mimeType: file.mime_type,
    sizeBytes: file.size_bytes,
    sha256: null,
    visibility: 'private',
    status: file.deleted_at ? 'deleted' : 'available',
    url: null,
    createdAt: file.created_at,
    updatedAt: file.updated_at,
  };
};

export const cloudPlanLabel = (plan: string) => {
  if (plan === 'plus_50gb') return 'Cloud +50';
  if (plan === 'plus_75gb') return 'Cloud +75';
  if (plan === 'custom') return 'Custom';
  return 'Free';
};

export const cloudAppUrl = (handle: string, page = 'files') =>
  `https://cloud.wersee.com/app/@${encodeURIComponent(handle || 'me')}/${page}`;
