import React, { useEffect, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { AudioLines, ChevronDown, MessageSquareText, Sparkles } from 'lucide-react';
import { resetLiquidGlassPointer, trackLiquidGlassPointer } from '../ui/LiquidGlass';

interface WorkspaceAiModeMenuProps {
  onOpenChat: () => void;
  onOpenVoice: () => void;
  voiceActive?: boolean;
  variant?: 'assistant' | 'topbar' | 'mobile';
}

const triggerClasses: Record<NonNullable<WorkspaceAiModeMenuProps['variant']>, string> = {
  assistant: 'wersee-liquid-glass wersee-liquid-glass--interactive flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-[10px] font-black uppercase tracking-widest text-indigo-300 xl:w-auto xl:px-4 xl:py-2',
  topbar: 'workspace-topbar-command flex h-10 items-center gap-2 rounded-full border border-white/[0.08] bg-white/[0.035] px-3 text-xs font-bold text-white/72 transition-colors hover:bg-white/[0.08] hover:text-white',
  mobile: 'wersee-liquid-glass wersee-liquid-glass--interactive flex h-11 w-11 shrink-0 items-center justify-center rounded-[17px] text-white/75 hover:text-white',
};

export const WorkspaceAiModeMenu: React.FC<WorkspaceAiModeMenuProps> = ({
  onOpenChat,
  onOpenVoice,
  voiceActive = false,
  variant = 'topbar',
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    const closeMenu = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setIsOpen(false);
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setIsOpen(false);
    };
    window.addEventListener('pointerdown', closeMenu);
    window.addEventListener('keydown', closeOnEscape);
    return () => {
      window.removeEventListener('pointerdown', closeMenu);
      window.removeEventListener('keydown', closeOnEscape);
    };
  }, [isOpen]);

  const selectMode = (openMode: () => void) => {
    setIsOpen(false);
    openMode();
  };

  return (
    <div ref={menuRef} className="relative shrink-0">
      <button
        type="button"
        onPointerMove={trackLiquidGlassPointer}
        onPointerLeave={resetLiquidGlassPointer}
        onClick={() => setIsOpen((open) => !open)}
        className={triggerClasses[variant]}
        aria-label="Choose Wersee AI mode"
        aria-haspopup="menu"
        aria-expanded={isOpen}
      >
        <span className="relative">
          <Sparkles className={variant === 'mobile' ? 'h-5 w-5' : 'h-4 w-4'} aria-hidden="true" />
          {voiceActive ? <span className="absolute -right-1 -top-1 h-1.5 w-1.5 rounded-full bg-emerald-300 shadow-[0_0_8px_rgba(110,231,183,0.95)]" /> : null}
        </span>
        {variant === 'assistant' ? <span className="ml-2 hidden xl:inline">Assistant</span> : null}
        {variant === 'topbar' ? <span className="hidden xl:inline">AI</span> : null}
        {variant !== 'mobile' ? <ChevronDown className={`h-3.5 w-3.5 transition-transform ${isOpen ? 'rotate-180' : ''}`} aria-hidden="true" /> : null}
      </button>

      <AnimatePresence>
        {isOpen ? (
          <motion.div
            initial={{ opacity: 0, y: 8, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 6, scale: 0.97 }}
            transition={{ type: 'spring', stiffness: 360, damping: 28 }}
            className="absolute right-0 top-[calc(100%+10px)] z-[90] w-[270px] origin-top-right overflow-hidden rounded-[24px] border border-white/[0.1] bg-[#111113]/96 p-2 text-white shadow-[0_24px_70px_rgba(0,0,0,0.58)] backdrop-blur-3xl"
            role="menu"
            aria-label="Wersee AI modes"
          >
            <p className="px-3 pb-2 pt-1.5 text-[10px] font-bold uppercase tracking-[0.16em] text-white/30">Choose a mode</p>
            <button
              type="button"
              role="menuitem"
              onClick={() => selectMode(onOpenChat)}
              className="group flex w-full items-center gap-3 rounded-[18px] px-3 py-3 text-left transition hover:bg-white/[0.065] focus-visible:bg-white/[0.065] focus-visible:outline-none"
            >
              <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/[0.09] bg-white/[0.045] text-violet-200">
                <MessageSquareText className="h-4.5 w-4.5" aria-hidden="true" />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block text-sm font-semibold text-white/90">Chat</span>
                <span className="mt-0.5 block text-[11px] text-white/38">Write with Wersee AI</span>
              </span>
            </button>
            <button
              type="button"
              role="menuitem"
              onClick={() => selectMode(onOpenVoice)}
              className="group mt-1 flex w-full items-center gap-3 rounded-[18px] px-3 py-3 text-left transition hover:bg-white/[0.065] focus-visible:bg-white/[0.065] focus-visible:outline-none"
            >
              <span className="relative grid h-10 w-10 shrink-0 place-items-center overflow-hidden rounded-full border border-cyan-200/20 bg-gradient-to-br from-violet-400/25 via-sky-400/20 to-emerald-300/20 text-cyan-100">
                <motion.span className="absolute inset-1 rounded-full border border-white/20" animate={{ scale: [0.74, 1.15, 0.74], opacity: [0.25, 0.75, 0.25] }} transition={{ duration: 2.2, repeat: Infinity, ease: 'easeInOut' }} />
                <AudioLines className="relative h-4.5 w-4.5" aria-hidden="true" />
              </span>
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-2 text-sm font-semibold text-white/90">Voice <span className="rounded-full bg-emerald-300/10 px-1.5 py-0.5 text-[8px] font-black uppercase tracking-[0.12em] text-emerald-200">Live</span></span>
                <span className="mt-0.5 block text-[11px] text-white/38">Talk and hear answers aloud</span>
              </span>
            </button>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
};
