import { safeLocalStorage } from './browserStorage';

export type WorkspaceViewType = 'topbar' | 'sidebar';

export const WORKSPACE_VIEW_TYPE_STORAGE_KEY = 'wersee:workspace-view-type';
export const WORKSPACE_VIEW_TYPE_EVENT = 'wersee:workspace-view-type-change';

export const isWorkspaceViewType = (value: unknown): value is WorkspaceViewType =>
  value === 'topbar' || value === 'sidebar';

export const getWorkspaceViewTypePreference = (): WorkspaceViewType => {
  const stored = safeLocalStorage.getItem(WORKSPACE_VIEW_TYPE_STORAGE_KEY);
  return isWorkspaceViewType(stored) ? stored : 'topbar';
};

export const setWorkspaceViewTypePreference = (viewType: WorkspaceViewType) => {
  safeLocalStorage.setItem(WORKSPACE_VIEW_TYPE_STORAGE_KEY, viewType);
  window.dispatchEvent(new CustomEvent<WorkspaceViewType>(WORKSPACE_VIEW_TYPE_EVENT, {
    detail: viewType,
  }));
};
