import React, { useCallback, useEffect, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import {
  AlertTriangle,
  BookOpen,
  Edit,
  Eye,
  Layers,
  Loader2,
  MoreHorizontal,
  Package,
  Plus,
  Search,
  SlidersHorizontal,
  Trash2,
  X,
} from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { appToast } from '../../lib/feedback';
import { supabase } from '../../lib/supabase';
import { DatabaseService } from '../../services/databaseService';
import { Skeleton } from '../ui/Skeleton';

interface Listing {
  id: string;
  title: string;
  price: number;
  status: string;
  views: number;
  sales: number;
  images: string[];
  category: string;
  type: string;
  created_at: string;
  is_sandbox?: boolean;
}

interface ManageProductsViewProps {
  onEdit?: (id: string) => void;
}

const priceFormatter = new Intl.NumberFormat('en-NL', {
  style: 'currency',
  currency: 'EUR',
  maximumFractionDigits: 2,
});

const dateFormatter = new Intl.DateTimeFormat('en', {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
});

const catalogTabs = [
  { id: 'products' as const, label: 'All listings', icon: Package },
  { id: 'courses' as const, label: 'Courses', icon: BookOpen },
  { id: 'bundles' as const, label: 'Bundles', icon: Layers },
];

const formatListingPrice = (listing: Listing) => {
  if (listing.type === 'service' || listing.category === 'job') return 'Job';
  return Number(listing.price) > 0 ? priceFormatter.format(Number(listing.price)) : 'Free';
};

const ListingSkeleton = () => (
  <div className="rounded-[1.75rem] border border-white/[0.07] bg-white/[0.025] p-3.5">
    <div className="flex items-center gap-3.5">
      <Skeleton className="h-[4.5rem] w-[4.5rem] shrink-0 rounded-[1.35rem]" />
      <div className="min-w-0 flex-1 space-y-2">
        <Skeleton className="h-4 w-2/3" />
        <Skeleton className="h-3 w-1/3" />
        <div className="flex gap-2 pt-1">
          <Skeleton className="h-7 w-16 rounded-full" />
          <Skeleton className="h-7 w-20 rounded-full" />
        </div>
      </div>
      <Skeleton className="hidden h-10 w-24 rounded-full sm:block" />
    </div>
  </div>
);

export const ManageProductsView: React.FC<ManageProductsViewProps> = ({ onEdit }) => {
  const [listings, setListings] = useState<Listing[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'products' | 'courses' | 'bundles'>('products');
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [listingToDelete, setListingToDelete] = useState<Listing | null>(null);
  const [deleteConfirmText, setDeleteConfirmText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [statusFilter, setStatusFilter] = useState<'all' | 'draft' | 'published' | 'archived'>('all');
  const [typeFilter, setTypeFilter] = useState('all');
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const { user } = useAuth();
  const prefersReducedMotion = useReducedMotion();

  const fetchListings = useCallback(async (retries = 3): Promise<void> => {
    if (!user) {
      setListings([]);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const data = await DatabaseService.get<Listing>('listings', {
        eq: { seller_id: user.id },
        order: { column: 'created_at', ascending: false },
      });
      setListings((data as Listing[]) || []);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : '';
      if (retries > 0 && (message.includes('fetch') || message.includes('Network'))) {
        await new Promise((resolve) => setTimeout(resolve, 2000));
        return fetchListings(retries - 1);
      }
      console.error('Error fetching listings:', error);
      appToast('Your product catalog could not be loaded.', 'error');
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    void fetchListings();
    if (!user) return;

    const channel = supabase
      .channel('listings-stats')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'listings',
          filter: `seller_id=eq.${user.id}`,
        },
        (payload) => {
          setListings((current) => current.map((listing) => (
            listing.id === payload.new.id ? { ...listing, ...payload.new } as Listing : listing
          )));
        },
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [fetchListings, user]);

  const handleDeleteClick = (listing: Listing) => {
    setListingToDelete(listing);
    setDeleteConfirmText('');
    setDeleteModalOpen(true);
  };

  const closeDeleteModal = () => {
    if (isDeleting) return;
    setDeleteModalOpen(false);
    setListingToDelete(null);
    setDeleteConfirmText('');
  };

  const confirmDelete = async () => {
    if (!listingToDelete || deleteConfirmText !== listingToDelete.title) return;

    try {
      setIsDeleting(true);
      await DatabaseService.delete('listings', listingToDelete.id);
      setListings((current) => current.filter((listing) => listing.id !== listingToDelete.id));
      appToast('Listing deleted.', 'success');
      setDeleteModalOpen(false);
      setListingToDelete(null);
      setDeleteConfirmText('');
    } catch (error) {
      console.error('Error deleting listing:', error);
      appToast('The listing could not be deleted.', 'error');
    } finally {
      setIsDeleting(false);
    }
  };

  const updateListingStatus = async (listing: Listing, status: 'draft' | 'published' | 'archived') => {
    try {
      await DatabaseService.update('listings', listing.id, { status });
      setListings((current) => current.map((item) => item.id === listing.id ? { ...item, status } : item));
      setOpenMenuId(null);
      appToast(status === 'published' ? 'Listing published.' : status === 'archived' ? 'Listing archived.' : 'Listing moved to drafts.', 'success');
    } catch (error) {
      console.error('Error updating listing status:', error);
      appToast('The listing status could not be updated.', 'error');
    }
  };

  const filteredListings = listings.filter((listing) => {
    const matchesSearch = listing.title.toLowerCase().includes(searchQuery.toLowerCase());
    if (!matchesSearch) return false;
    if (statusFilter !== 'all' && listing.status !== statusFilter) return false;
    if (typeFilter !== 'all' && listing.type !== typeFilter) return false;
    if (activeTab === 'bundles') return listing.type === 'bundle';
    if (activeTab === 'courses') return listing.category === 'course';
    return listing.type !== 'bundle';
  });

  const tabCounts = listings.reduce((counts, listing) => {
    if (listing.type !== 'bundle') counts.products += 1;
    if (listing.category === 'course') counts.courses += 1;
    if (listing.type === 'bundle') counts.bundles += 1;
    return counts;
  }, { products: 0, courses: 0, bundles: 0 });
  const activeFilterCount = Number(statusFilter !== 'all') + Number(typeFilter !== 'all');
  const hasQueryOrFilters = searchQuery.trim().length > 0 || activeFilterCount > 0;
  const createLabel = activeTab === 'bundles' ? 'Bundle' : activeTab === 'courses' ? 'Course' : 'Listing';

  const resetFilters = () => {
    setSearchQuery('');
    setStatusFilter('all');
    setTypeFilter('all');
    setFiltersOpen(false);
  };

  return (
    <div className="mx-auto max-w-7xl space-y-4 p-4 md:p-7">
      <header className="flex flex-col gap-4 px-1 sm:flex-row sm:items-end sm:justify-between">
        <div className="min-w-0">
          <div className="mb-2 flex flex-wrap items-center gap-2">
            <span className="inline-flex items-center gap-2 rounded-full border border-indigo-400/15 bg-indigo-400/[0.08] px-3 py-1 text-[10px] font-black uppercase tracking-[0.18em] text-indigo-200">
              <Package className="h-3.5 w-3.5" /> Product catalog
            </span>
            <span className="rounded-full border border-white/[0.08] bg-white/[0.035] px-3 py-1 text-[10px] font-bold text-white/45">
              {listings.length} {listings.length === 1 ? 'listing' : 'listings'}
            </span>
          </div>
          <h1 className="text-2xl font-black tracking-tight text-white sm:text-3xl">Products</h1>
          <p className="mt-1 text-sm text-white/40">Create, publish and manage everything you sell.</p>
        </div>
        <button
          type="button"
          onClick={() => onEdit?.('create-listing')}
          className="inline-flex min-h-11 w-full items-center justify-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black transition hover:bg-indigo-100 active:scale-[0.98] sm:w-auto"
        >
          <Plus className="h-4 w-4" /> Create {createLabel}
        </button>
      </header>

      <section className="rounded-[1.8rem] border border-white/[0.07] bg-white/[0.025] p-2.5" aria-label="Product controls">
        <div className="flex flex-col gap-2.5 lg:flex-row lg:items-center">
          <div className="flex min-w-0 items-center gap-1 overflow-x-auto rounded-full border border-white/[0.07] bg-black/25 p-1 scrollbar-hide" role="tablist" aria-label="Product types">
            {catalogTabs.map((tab) => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  type="button"
                  role="tab"
                  aria-selected={activeTab === tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`inline-flex min-h-10 shrink-0 items-center gap-2 rounded-full px-3.5 text-xs font-bold transition ${
                    activeTab === tab.id ? 'bg-white text-black shadow-lg shadow-black/20' : 'text-white/40 hover:bg-white/[0.05] hover:text-white'
                  }`}
                >
                  <Icon className="h-3.5 w-3.5" />
                  {tab.label}
                  <span className={`rounded-full px-1.5 py-0.5 text-[9px] ${activeTab === tab.id ? 'bg-black/10 text-black/60' : 'bg-white/[0.06] text-white/35'}`}>
                    {tabCounts[tab.id]}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="relative min-w-0 flex-1">
            <Search className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" />
            <input
              type="search"
              aria-label="Search listings"
              placeholder="Search your catalog"
              value={searchQuery}
              onChange={(event) => setSearchQuery(event.target.value)}
              className="h-11 w-full rounded-full border border-white/[0.07] bg-black/25 pl-11 pr-10 text-sm text-white outline-none placeholder:text-white/25 focus:border-indigo-400/35 focus:bg-white/[0.035]"
            />
            {searchQuery && (
              <button type="button" onClick={() => setSearchQuery('')} className="absolute right-2 top-1/2 grid h-8 w-8 -translate-y-1/2 place-items-center rounded-full text-white/30 hover:bg-white/[0.07] hover:text-white" aria-label="Clear search">
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>

          <div className="relative">
            <button
              type="button"
              aria-label="Filter listings"
              aria-expanded={filtersOpen}
              onClick={() => setFiltersOpen((open) => !open)}
              className={`inline-flex h-11 w-full items-center justify-center gap-2 rounded-full border px-4 text-xs font-bold transition lg:w-auto ${
                filtersOpen || activeFilterCount > 0
                  ? 'border-indigo-400/25 bg-indigo-400/10 text-indigo-200'
                  : 'border-white/[0.07] bg-black/25 text-white/45 hover:bg-white/[0.05] hover:text-white'
              }`}
            >
              <SlidersHorizontal className="h-3.5 w-3.5" /> Filters
              {activeFilterCount > 0 && <span className="grid h-5 min-w-5 place-items-center rounded-full bg-indigo-300 px-1 text-[9px] font-black text-black">{activeFilterCount}</span>}
            </button>
            <AnimatePresence>
              {filtersOpen && (
                <motion.div
                  initial={{ opacity: 0, y: -8, scale: 0.98 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: -8, scale: 0.98 }}
                  className="absolute right-0 top-[3.25rem] z-40 w-[min(20rem,calc(100vw-2rem))] rounded-[1.65rem] border border-white/10 bg-[#18181b] p-4 shadow-2xl shadow-black/60"
                >
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-black text-white">Filter catalog</p>
                    <button type="button" onClick={() => setFiltersOpen(false)} className="grid h-8 w-8 place-items-center rounded-full text-white/35 hover:bg-white/[0.07] hover:text-white" aria-label="Close filters"><X className="h-4 w-4" /></button>
                  </div>
                  <label className="mt-4 block text-[10px] font-bold uppercase tracking-widest text-white/30" htmlFor="listing-status-filter">Status</label>
                  <select id="listing-status-filter" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)} className="mt-2 h-11 w-full rounded-full border border-white/10 bg-black/40 px-4 text-sm text-white outline-none focus:border-indigo-400/40">
                    <option value="all">All statuses</option>
                    <option value="published">Published</option>
                    <option value="draft">Draft</option>
                    <option value="archived">Archived</option>
                  </select>
                  <label className="mt-4 block text-[10px] font-bold uppercase tracking-widest text-white/30" htmlFor="listing-type-filter">Listing type</label>
                  <select id="listing-type-filter" value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)} className="mt-2 h-11 w-full rounded-full border border-white/10 bg-black/40 px-4 text-sm capitalize text-white outline-none focus:border-indigo-400/40">
                    <option value="all">All types</option>
                    {Array.from(new Set(listings.map((listing) => listing.type).filter(Boolean))).sort().map((type) => (
                      <option key={type} value={type}>{type.replace(/_/g, ' ')}</option>
                    ))}
                  </select>
                  <button type="button" onClick={resetFilters} className="mt-4 h-10 w-full rounded-full bg-white/[0.06] px-3 text-xs font-bold text-white/60 hover:bg-white/10 hover:text-white">
                    Reset filters
                  </button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        {activeFilterCount > 0 && (
          <div className="mt-2 flex flex-wrap items-center gap-1.5 px-1">
            {statusFilter !== 'all' && <span className="rounded-full border border-white/[0.07] bg-white/[0.035] px-3 py-1 text-[10px] font-bold capitalize text-white/45">Status: {statusFilter}</span>}
            {typeFilter !== 'all' && <span className="rounded-full border border-white/[0.07] bg-white/[0.035] px-3 py-1 text-[10px] font-bold capitalize text-white/45">Type: {typeFilter.replace(/_/g, ' ')}</span>}
            <button type="button" onClick={resetFilters} className="rounded-full px-2.5 py-1 text-[10px] font-bold text-indigo-300 hover:bg-indigo-400/10">Clear all</button>
          </div>
        )}
      </section>

      <section aria-live="polite" aria-busy={loading}>
        {loading ? (
          <div className="space-y-2.5">
            <ListingSkeleton />
            <ListingSkeleton />
            <ListingSkeleton />
          </div>
        ) : filteredListings.length === 0 ? (
          <div className="rounded-[2rem] border border-dashed border-white/10 bg-white/[0.02] px-5 py-14 text-center">
            <div className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-white/[0.08] bg-white/[0.035]">
              {hasQueryOrFilters ? <Search className="h-6 w-6 text-white/25" /> : <Package className="h-6 w-6 text-white/25" />}
            </div>
            <h2 className="mt-4 text-lg font-black text-white">{hasQueryOrFilters ? 'No matching listings' : `No ${activeTab} yet`}</h2>
            <p className="mx-auto mt-1 max-w-md text-sm leading-6 text-white/35">
              {hasQueryOrFilters ? 'Try another search or remove a filter to see more of your catalog.' : `Create your first ${createLabel.toLowerCase()} to start selling.`}
            </p>
            <button
              type="button"
              onClick={hasQueryOrFilters ? resetFilters : () => onEdit?.('create-listing')}
              className="mt-5 inline-flex h-11 items-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black hover:bg-indigo-100"
            >
              {hasQueryOrFilters ? <X className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
              {hasQueryOrFilters ? 'Clear search and filters' : `Create ${createLabel}`}
            </button>
          </div>
        ) : (
          <div className="space-y-2.5">
            {filteredListings.map((listing) => (
              <motion.article
                key={listing.id}
                initial={prefersReducedMotion ? false : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="group relative rounded-[1.75rem] border border-white/[0.07] bg-[#101012] p-3.5 transition hover:border-indigo-400/25 hover:bg-white/[0.035]"
              >
                <div className="flex min-w-0 items-center gap-3.5">
                  <div className="relative h-[4.5rem] w-[4.5rem] shrink-0 overflow-hidden rounded-[1.35rem] border border-white/[0.07] bg-white/[0.035]">
                    {listing.images?.[0] ? (
                      <img src={listing.images[0]} alt="" className="h-full w-full object-cover transition duration-500 group-hover:scale-105" referrerPolicy="no-referrer" />
                    ) : (
                      <div className="grid h-full w-full place-items-center text-white/20"><Package className="h-6 w-6" /></div>
                    )}
                  </div>

                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-1.5">
                      <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[9px] font-black uppercase tracking-[0.12em] ${
                        listing.status === 'published'
                          ? 'border-emerald-400/20 bg-emerald-400/[0.08] text-emerald-300'
                          : listing.status === 'archived'
                            ? 'border-white/10 bg-white/[0.04] text-white/35'
                            : 'border-amber-400/20 bg-amber-400/[0.08] text-amber-300'
                      }`}>
                        <span className="h-1.5 w-1.5 rounded-full bg-current" /> {listing.status}
                      </span>
                      <span className="rounded-full border border-white/[0.07] bg-white/[0.035] px-2.5 py-1 text-[9px] font-bold capitalize text-white/35">
                        {(listing.type || 'product').replace(/_/g, ' ')}
                      </span>
                      {listing.is_sandbox && <span className="rounded-full border border-amber-400/20 bg-amber-400/[0.08] px-2.5 py-1 text-[9px] font-black uppercase tracking-wider text-amber-300">Sandbox</span>}
                    </div>
                    <h2 className="mt-1.5 truncate text-base font-black text-white transition group-hover:text-indigo-200 sm:text-lg">{listing.title}</h2>
                    <p className="mt-0.5 truncate text-xs text-white/30">{listing.category || 'Uncategorized'} &middot; Added {dateFormatter.format(new Date(listing.created_at))}</p>
                  </div>

                  <span className="hidden shrink-0 rounded-full border border-white/[0.08] bg-white/[0.04] px-4 py-2 text-sm font-black text-white sm:inline-flex">
                    {formatListingPrice(listing)}
                  </span>
                </div>

                <div className="mt-3 flex flex-wrap items-center gap-2 border-t border-white/[0.05] pt-3 sm:ml-[5.4rem] sm:border-0 sm:pt-0">
                  <span className="inline-flex h-8 items-center gap-1.5 rounded-full bg-white/[0.035] px-3 text-[10px] font-bold text-white/40">
                    <Eye className="h-3.5 w-3.5 text-indigo-300" /> {listing.views || 0} views
                  </span>
                  <span className="inline-flex h-8 items-center gap-1.5 rounded-full bg-white/[0.035] px-3 text-[10px] font-bold text-white/40">
                    <Package className="h-3.5 w-3.5 text-indigo-300" /> {listing.sales || 0} sales
                  </span>
                  <span className="inline-flex h-8 items-center rounded-full border border-white/[0.08] bg-white/[0.04] px-3 text-xs font-black text-white sm:hidden">{formatListingPrice(listing)}</span>

                  <div className="ml-auto flex items-center gap-1.5">
                    <button type="button" onClick={() => onEdit?.(listing.id)} className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.07] bg-white/[0.035] text-white/45 transition hover:border-indigo-400/25 hover:bg-indigo-400/10 hover:text-indigo-200" aria-label={`Edit ${listing.title}`} title="Edit listing">
                      <Edit className="h-4 w-4" />
                    </button>
                    <button type="button" onClick={() => handleDeleteClick(listing)} className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.07] bg-white/[0.035] text-white/45 transition hover:border-red-400/25 hover:bg-red-400/10 hover:text-red-300" aria-label={`Delete ${listing.title}`} title="Delete listing">
                      <Trash2 className="h-4 w-4" />
                    </button>
                    <div className="relative">
                      <button
                        type="button"
                        aria-label={`More actions for ${listing.title}`}
                        aria-expanded={openMenuId === listing.id}
                        onClick={() => setOpenMenuId((current) => current === listing.id ? null : listing.id)}
                        className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.07] bg-white/[0.035] text-white/45 transition hover:bg-white/[0.08] hover:text-white"
                      >
                        <MoreHorizontal className="h-4 w-4" />
                      </button>
                      <AnimatePresence>
                        {openMenuId === listing.id && (
                          <motion.div
                            initial={{ opacity: 0, scale: 0.96, y: -6 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.96, y: -6 }}
                            className="absolute right-0 top-12 z-30 w-48 overflow-hidden rounded-[1.35rem] border border-white/10 bg-[#1a1a1d] p-1.5 shadow-2xl shadow-black/60"
                          >
                            <button type="button" onClick={() => { setOpenMenuId(null); onEdit?.(listing.id); }} className="w-full rounded-full px-3 py-2.5 text-left text-sm text-white/70 hover:bg-white/[0.07] hover:text-white">Edit listing</button>
                            {listing.status !== 'published' && <button type="button" onClick={() => void updateListingStatus(listing, 'published')} className="w-full rounded-full px-3 py-2.5 text-left text-sm text-emerald-300 hover:bg-emerald-400/10">Publish</button>}
                            {listing.status === 'published' && <button type="button" onClick={() => void updateListingStatus(listing, 'draft')} className="w-full rounded-full px-3 py-2.5 text-left text-sm text-amber-300 hover:bg-amber-400/10">Move to drafts</button>}
                            {listing.status !== 'archived' && <button type="button" onClick={() => void updateListingStatus(listing, 'archived')} className="w-full rounded-full px-3 py-2.5 text-left text-sm text-white/60 hover:bg-white/[0.07]">Archive</button>}
                            <button type="button" onClick={() => { setOpenMenuId(null); handleDeleteClick(listing); }} className="w-full rounded-full px-3 py-2.5 text-left text-sm text-red-300 hover:bg-red-400/10">Delete</button>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </div>
              </motion.article>
            ))}
          </div>
        )}
      </section>

      <AnimatePresence>
        {deleteModalOpen && (
          <div className="fixed inset-0 z-[300] flex items-center justify-center p-4" role="dialog" aria-modal="true" aria-labelledby="delete-listing-title">
            <motion.button
              type="button"
              aria-label="Close delete confirmation"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={closeDeleteModal}
              className="absolute inset-0 bg-black/80 backdrop-blur-sm"
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="relative w-full max-w-md overflow-hidden rounded-[2rem] border border-white/10 bg-[#141416] shadow-2xl"
            >
              <div className="p-6">
                <div className="flex items-center gap-3.5">
                  <div className="grid h-12 w-12 shrink-0 place-items-center rounded-full bg-red-500/10">
                    <AlertTriangle className="h-5 w-5 text-red-400" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <h2 id="delete-listing-title" className="text-lg font-black text-white">Delete listing?</h2>
                    <p className="text-sm text-white/35">This action cannot be undone.</p>
                  </div>
                  <button type="button" onClick={closeDeleteModal} disabled={isDeleting} className="grid h-10 w-10 place-items-center rounded-full text-white/35 hover:bg-white/[0.06] hover:text-white disabled:opacity-30" aria-label="Close">
                    <X className="h-4 w-4" />
                  </button>
                </div>

                <div className="mt-5 rounded-[1.5rem] border border-white/[0.07] bg-white/[0.035] p-4">
                  <p className="text-sm leading-6 text-white/40">Type the product name to confirm:</p>
                  <p className="mt-1 truncate text-sm font-black text-white">{listingToDelete?.title}</p>
                  <input
                    type="text"
                    value={deleteConfirmText}
                    onChange={(event) => setDeleteConfirmText(event.target.value)}
                    placeholder="Product name"
                    className="mt-3 h-11 w-full rounded-full border border-white/10 bg-black/40 px-4 text-sm text-white outline-none placeholder:text-white/20 focus:border-red-400/45"
                    autoFocus
                  />
                </div>

                <div className="mt-5 flex gap-2">
                  <button type="button" onClick={closeDeleteModal} disabled={isDeleting} className="h-11 flex-1 rounded-full px-4 text-sm font-bold text-white/45 hover:bg-white/[0.06] hover:text-white disabled:opacity-30">
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={() => void confirmDelete()}
                    disabled={isDeleting || deleteConfirmText !== listingToDelete?.title}
                    className="inline-flex h-11 flex-1 items-center justify-center gap-2 rounded-full bg-red-500 px-4 text-sm font-black text-white transition hover:bg-red-400 disabled:cursor-not-allowed disabled:bg-red-500/15 disabled:text-red-300/35"
                  >
                    {isDeleting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                    Delete forever
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};
