import React, { useEffect, useState } from 'react';
import {
  AlertCircle,
  Building2,
  Check,
  Crown,
  Hash,
  Loader2,
  MailPlus,
  Plus,
  ShieldCheck,
  Users,
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { hapticFeedback } from '../../lib/haptics';
import { BottomSheetModal } from '../ui/BottomSheetModal';

export type BusinessChat = {
  id: string;
  owner_id: string;
  name: string;
  description: string;
  avatar_url: string | null;
  role: 'owner' | 'admin' | 'member';
  created_at?: string;
};

export type BusinessChatMember = {
  business_chat_id: string;
  user_id: string;
  role: 'owner' | 'admin' | 'member';
  joined_at: string;
  profile?: {
    id: string;
    name: string | null;
    full_name: string | null;
    username: string | null;
    avatar_url: string | null;
  } | null;
};

export type BusinessChatChannel = {
  id: string;
  business_chat_id: string;
  chat_id: string;
  name: string;
  description: string;
  position: number;
  created_at: string;
  chat?: {
    id: string;
    last_message: string | null;
    last_message_at: string | null;
    metadata: Record<string, unknown> | null;
  } | null;
};

const messageFrom = (reason: unknown, fallback: string) => {
  if (reason && typeof reason === 'object' && 'message' in reason) {
    return String((reason as { message?: unknown }).message || fallback);
  }
  return fallback;
};

type CreateBusinessChatModalProps = {
  isOpen: boolean;
  businessChats: BusinessChat[];
  onClose: () => void;
  onCreated: (businessChatId: string, chatId: string) => Promise<void> | void;
  onOpenBusiness: (businessChatId: string) => void;
};

export function CreateBusinessChatModal({
  isOpen,
  businessChats,
  onClose,
  onCreated,
  onOpenBusiness,
}: CreateBusinessChatModalProps) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!isOpen) {
      setError('');
      setIsCreating(false);
    }
  }, [isOpen]);

  const createBusinessChat = async (event: React.FormEvent) => {
    event.preventDefault();
    if (isCreating || !name.trim()) return;
    setIsCreating(true);
    setError('');
    try {
      const { data, error: rpcError } = await supabase.rpc('create_business_chat', {
        p_name: name.trim(),
        p_description: description.trim(),
      });
      if (rpcError) throw rpcError;
      const result = data as { business_chat_id?: string; chat_id?: string } | null;
      if (!result?.business_chat_id || !result.chat_id) {
        throw new Error('Wersee did not return the new business chat.');
      }
      hapticFeedback('success');
      setName('');
      setDescription('');
      await onCreated(result.business_chat_id, result.chat_id);
      onClose();
    } catch (reason) {
      setError(messageFrom(reason, 'The business chat could not be created.'));
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <BottomSheetModal isOpen={isOpen} onClose={onClose} maxWidth="max-w-xl" title="Business chats">
      <div className="grid gap-6 p-5 md:p-7">
        {businessChats.length > 0 && (
          <section aria-labelledby="your-business-chats">
            <h3 id="your-business-chats" className="mb-3 text-xs font-bold uppercase tracking-[0.14em] text-white/45">
              Your business chats
            </h3>
            <div className="grid gap-2 sm:grid-cols-2">
              {businessChats.map((business) => (
                <button
                  key={business.id}
                  type="button"
                  onClick={() => {
                    hapticFeedback('light');
                    onOpenBusiness(business.id);
                    onClose();
                  }}
                  className="chat-create-choice flex min-h-20 items-center gap-3 rounded-2xl border p-3.5 text-left transition-transform active:scale-[0.98]"
                >
                  <span className="grid h-11 w-11 shrink-0 place-items-center overflow-hidden rounded-2xl bg-violet-500/15 text-violet-300">
                    {business.avatar_url
                      ? <img src={business.avatar_url} alt="" className="h-full w-full object-cover" />
                      : <Building2 className="h-5 w-5" />}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-bold">{business.name}</span>
                    <span className="mt-1 flex items-center gap-1 text-[11px] capitalize opacity-50">
                      {business.role === 'owner' ? <Crown className="h-3 w-3" /> : <Users className="h-3 w-3" />}
                      {business.role}
                    </span>
                  </span>
                </button>
              ))}
            </div>
          </section>
        )}

        <form onSubmit={createBusinessChat} className="grid gap-4">
          <div>
            <h3 className="text-lg font-bold text-white">Create a business chat</h3>
            <p className="mt-1 text-sm leading-5 text-white/45">
              Start with a shared #general channel. You can invite members and add more channels next.
            </p>
          </div>

          {error && (
            <div className="flex items-start gap-3 rounded-2xl border border-red-400/20 bg-red-400/10 p-3.5 text-sm text-red-100" role="alert">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <label className="grid gap-2">
            <span className="text-xs font-bold uppercase tracking-[0.12em] text-white/45">Name</span>
            <input
              value={name}
              onChange={(event) => setName(event.target.value.slice(0, 80))}
              placeholder="e.g. Wersee Studio"
              autoComplete="organization"
              autoFocus
              className="chat-action-input min-h-12 w-full rounded-2xl border px-4 text-sm outline-none"
            />
          </label>

          <label className="grid gap-2">
            <span className="flex items-center justify-between text-xs font-bold uppercase tracking-[0.12em] text-white/45">
              Description
              <span className="font-normal normal-case tracking-normal">{description.length}/500</span>
            </span>
            <textarea
              value={description}
              onChange={(event) => setDescription(event.target.value.slice(0, 500))}
              placeholder="What will your team use this space for?"
              className="chat-action-input min-h-24 w-full resize-y rounded-2xl border px-4 py-3 text-sm outline-none"
            />
          </label>

          <button
            type="submit"
            disabled={isCreating || !name.trim()}
            className="flex min-h-12 items-center justify-center gap-2 rounded-2xl bg-white px-5 text-sm font-bold text-black transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-45"
          >
            {isCreating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
            Create business chat
          </button>
        </form>
      </div>
    </BottomSheetModal>
  );
}

type ManageBusinessChatModalProps = {
  isOpen: boolean;
  businessChat: BusinessChat | null;
  members: BusinessChatMember[];
  onClose: () => void;
  onChanged: (preferredChatId?: string) => Promise<void> | void;
};

export function ManageBusinessChatModal({
  isOpen,
  businessChat,
  members,
  onClose,
  onChanged,
}: ManageBusinessChatModalProps) {
  const [email, setEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<'admin' | 'member'>('member');
  const [channelName, setChannelName] = useState('');
  const [channelDescription, setChannelDescription] = useState('');
  const [busyAction, setBusyAction] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const isOwner = businessChat?.role === 'owner';
  const canManage = businessChat?.role === 'owner' || businessChat?.role === 'admin';

  useEffect(() => {
    if (!isOpen) {
      setError('');
      setSuccess('');
      setBusyAction('');
    }
  }, [isOpen]);

  if (!businessChat) return null;

  const inviteMember = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!email.trim() || busyAction) return;
    setBusyAction('invite');
    setError('');
    setSuccess('');
    try {
      const { data, error: functionError } = await supabase.functions.invoke('business-chat-invite', {
        body: {
          businessChatId: businessChat.id,
          email: email.trim(),
          role: inviteRole,
        },
      });
      if (functionError) throw functionError;
      if (data?.error) throw new Error(data.error.message || 'The invitation could not be sent.');
      setEmail('');
      setSuccess('Invitation sent with Resend. The link expires in 7 days.');
      hapticFeedback('success');
    } catch (reason) {
      setError(messageFrom(reason, 'The invitation could not be sent.'));
    } finally {
      setBusyAction('');
    }
  };

  const createChannel = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!channelName.trim() || busyAction) return;
    setBusyAction('channel');
    setError('');
    setSuccess('');
    try {
      const { data, error: rpcError } = await supabase.rpc('create_business_chat_channel', {
        p_business_chat_id: businessChat.id,
        p_name: channelName.trim(),
        p_description: channelDescription.trim(),
      });
      if (rpcError) throw rpcError;
      const chatId = (data as { chat_id?: string } | null)?.chat_id;
      setChannelName('');
      setChannelDescription('');
      setSuccess('Channel created for everyone in this business chat.');
      await onChanged(chatId);
      hapticFeedback('success');
    } catch (reason) {
      setError(messageFrom(reason, 'The channel could not be created.'));
    } finally {
      setBusyAction('');
    }
  };

  const updateRole = async (userId: string, role: 'admin' | 'member') => {
    if (busyAction) return;
    setBusyAction(`role:${userId}`);
    setError('');
    setSuccess('');
    try {
      const { error: rpcError } = await supabase.rpc('update_business_chat_member_role', {
        p_business_chat_id: businessChat.id,
        p_user_id: userId,
        p_role: role,
      });
      if (rpcError) throw rpcError;
      await onChanged();
      setSuccess('Member role updated.');
    } catch (reason) {
      setError(messageFrom(reason, 'The role could not be updated.'));
    } finally {
      setBusyAction('');
    }
  };

  return (
    <BottomSheetModal isOpen={isOpen} onClose={onClose} maxWidth="max-w-2xl" title={`Manage ${businessChat.name}`}>
      <div className="grid gap-6 p-5 md:grid-cols-2 md:p-7">
        {(error || success) && (
          <div
            className={`flex items-start gap-3 rounded-2xl border p-3.5 text-sm md:col-span-2 ${
              error
                ? 'border-red-400/20 bg-red-400/10 text-red-100'
                : 'border-emerald-400/20 bg-emerald-400/10 text-emerald-100'
            }`}
            role={error ? 'alert' : 'status'}
          >
            {error ? <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> : <Check className="mt-0.5 h-4 w-4 shrink-0" />}
            <span>{error || success}</span>
          </div>
        )}

        <form onSubmit={inviteMember} className="grid content-start gap-4 rounded-3xl border border-white/10 bg-white/[0.035] p-4">
          <span className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-500/15 text-blue-300">
            <MailPlus className="h-5 w-5" />
          </span>
          <div>
            <h3 className="font-bold text-white">Invite by email</h3>
            <p className="mt-1 text-xs leading-5 text-white/45">Resend sends a personal, email-bound join link.</p>
          </div>
          <input
            type="email"
            value={email}
            onChange={(event) => setEmail(event.target.value.slice(0, 320))}
            placeholder="name@company.com"
            autoComplete="email"
            className="chat-action-input min-h-11 w-full rounded-xl border px-3 text-sm outline-none"
          />
          <select
            value={inviteRole}
            onChange={(event) => setInviteRole(event.target.value as 'admin' | 'member')}
            className="chat-action-input min-h-11 w-full rounded-xl border px-3 text-sm outline-none"
            aria-label="Invitation role"
          >
            <option value="member">Member</option>
            {isOwner && <option value="admin">Admin</option>}
          </select>
          <button
            type="submit"
            disabled={!canManage || !email.trim() || Boolean(busyAction)}
            className="flex min-h-11 items-center justify-center gap-2 rounded-xl bg-blue-500 px-4 text-sm font-bold text-white disabled:opacity-40"
          >
            {busyAction === 'invite' && <Loader2 className="h-4 w-4 animate-spin" />}
            Send invite
          </button>
        </form>

        <form onSubmit={createChannel} className="grid content-start gap-4 rounded-3xl border border-white/10 bg-white/[0.035] p-4">
          <span className="grid h-11 w-11 place-items-center rounded-2xl bg-violet-500/15 text-violet-300">
            <Hash className="h-5 w-5" />
          </span>
          <div>
            <h3 className="font-bold text-white">Add a channel</h3>
            <p className="mt-1 text-xs leading-5 text-white/45">Every current member gets access automatically.</p>
          </div>
          <input
            value={channelName}
            onChange={(event) => setChannelName(event.target.value.slice(0, 60))}
            placeholder="announcements"
            className="chat-action-input min-h-11 w-full rounded-xl border px-3 text-sm outline-none"
          />
          <input
            value={channelDescription}
            onChange={(event) => setChannelDescription(event.target.value.slice(0, 240))}
            placeholder="Optional description"
            className="chat-action-input min-h-11 w-full rounded-xl border px-3 text-sm outline-none"
          />
          <button
            type="submit"
            disabled={!canManage || !channelName.trim() || Boolean(busyAction)}
            className="flex min-h-11 items-center justify-center gap-2 rounded-xl bg-violet-500 px-4 text-sm font-bold text-white disabled:opacity-40"
          >
            {busyAction === 'channel' && <Loader2 className="h-4 w-4 animate-spin" />}
            Create channel
          </button>
        </form>

        <section className="md:col-span-2" aria-labelledby="business-member-roles">
          <div className="mb-3 flex items-center justify-between gap-3">
            <div>
              <h3 id="business-member-roles" className="font-bold text-white">Members and roles</h3>
              <p className="mt-1 text-xs text-white/45">
                {isOwner ? 'Only the owner can promote or demote members.' : 'Roles are managed by the owner.'}
              </p>
            </div>
            <span className="rounded-full bg-white/[0.06] px-3 py-1.5 text-xs font-bold text-white/55">
              {members.length} {members.length === 1 ? 'member' : 'members'}
            </span>
          </div>
          <div className="grid gap-2">
            {members.map((member) => {
              const name = member.profile?.full_name || member.profile?.name || member.profile?.username || 'Wersee member';
              return (
                <div key={member.user_id} className="flex min-h-16 items-center gap-3 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-3">
                  <span className="grid h-10 w-10 shrink-0 place-items-center overflow-hidden rounded-full bg-white/[0.08] text-xs font-bold">
                    {member.profile?.avatar_url
                      ? <img src={member.profile.avatar_url} alt="" className="h-full w-full object-cover" />
                      : name.slice(0, 2).toUpperCase()}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-semibold text-white">{name}</span>
                    <span className="mt-0.5 flex items-center gap-1 text-[11px] capitalize text-white/40">
                      {member.role === 'owner'
                        ? <Crown className="h-3 w-3 text-amber-300" />
                        : member.role === 'admin'
                          ? <ShieldCheck className="h-3 w-3 text-blue-300" />
                          : <Users className="h-3 w-3" />}
                      {member.role}
                    </span>
                  </span>
                  {isOwner && member.role !== 'owner' ? (
                    <select
                      value={member.role}
                      onChange={(event) => void updateRole(member.user_id, event.target.value as 'admin' | 'member')}
                      disabled={Boolean(busyAction)}
                      aria-label={`Role for ${name}`}
                      className="chat-action-input min-h-10 rounded-xl border px-3 text-xs font-semibold outline-none disabled:opacity-50"
                    >
                      <option value="member">Member</option>
                      <option value="admin">Admin</option>
                    </select>
                  ) : (
                    <span className="rounded-full bg-white/[0.06] px-2.5 py-1 text-[10px] font-bold capitalize text-white/50">
                      {member.role}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      </div>
    </BottomSheetModal>
  );
}
