import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import {
  Users,
  Search,
  Plus,
  ChevronRight,
  MessageSquare,
  ShieldCheck,
  Globe2,
  LockKeyhole,
  RefreshCw,
} from 'lucide-react';
import { supabase } from '../../lib/supabase';

interface CommunitiesListViewProps {
  onNavigate: (view: string) => void;
}

type CommunityListItem = {
  id: string;
  owner_id: string;
  name: string;
  description: string | null;
  logo_url: string | null;
  banner_url: string | null;
  is_private: boolean | null;
  privacy_level: string | null;
  created_at: string;
  member_count: number;
  channel_count: number;
  latest_message_at: string | null;
};

export const CommunitiesListView: React.FC<CommunitiesListViewProps> = ({ onNavigate }) => {
  const [communities, setCommunities] = useState<CommunityListItem[]>([]);
  const [userId, setUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const fetchCommunities = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const { data: authData, error: authError } = await supabase.auth.getUser();
      if (authError) throw authError;
      const currentUserId = authData.user?.id;
      if (!currentUserId) throw new Error('Sign in to view your communities.');
      setUserId(currentUserId);

      const [{ data: owned, error: ownedError }, { data: memberships, error: membershipError }] = await Promise.all([
        supabase.from('communities').select('*').eq('owner_id', currentUserId),
        supabase.from('community_members').select('community_id').eq('user_id', currentUserId),
      ]);

      if (ownedError) throw ownedError;
      if (membershipError) throw membershipError;

      const ids = Array.from(new Set([
        ...(owned || []).map((community) => community.id),
        ...(memberships || []).map((membership) => membership.community_id),
      ]));

      if (ids.length === 0) {
        setCommunities([]);
        return;
      }

      const [{ data: joined, error: joinedError }, { data: members }, { data: channels }] = await Promise.all([
        supabase.from('communities').select('*').in('id', ids),
        supabase.from('community_members').select('community_id').in('community_id', ids),
        supabase.from('community_channels').select('id, community_id').in('community_id', ids),
      ]);
      if (joinedError) throw joinedError;

      const memberCounts = new Map<string, number>();
      (members || []).forEach((member) => {
        memberCounts.set(member.community_id, (memberCounts.get(member.community_id) || 0) + 1);
      });

      const channelCounts = new Map<string, number>();
      const channelToCommunity = new Map<string, string>();
      (channels || []).forEach((channel) => {
        channelCounts.set(channel.community_id, (channelCounts.get(channel.community_id) || 0) + 1);
        channelToCommunity.set(channel.id, channel.community_id);
      });

      let latestMessages: Array<{ channel_id: string; created_at: string }> = [];
      const channelIds = Array.from(channelToCommunity.keys());
      if (channelIds.length > 0) {
        const { data } = await supabase
          .from('community_messages')
          .select('channel_id, created_at')
          .in('channel_id', channelIds)
          .order('created_at', { ascending: false });
        latestMessages = data || [];
      }

      const latestByCommunity = new Map<string, string>();
      latestMessages.forEach((message) => {
        const communityId = channelToCommunity.get(message.channel_id);
        if (communityId && !latestByCommunity.has(communityId)) {
          latestByCommunity.set(communityId, message.created_at);
        }
      });

      setCommunities((joined || []).map((community) => ({
        ...community,
        member_count: memberCounts.get(community.id) || 0,
        channel_count: channelCounts.get(community.id) || 0,
        latest_message_at: latestByCommunity.get(community.id) || null,
      })));
    } catch (fetchError: any) {
      console.error('Error fetching communities:', fetchError);
      setError(fetchError?.message || 'Communities could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchCommunities();
  }, [fetchCommunities]);

  useEffect(() => {
    if (!userId) return;

    const channel = supabase
      .channel(`workspace-communities:${userId}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'community_members', filter: `user_id=eq.${userId}` }, fetchCommunities)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'communities', filter: `owner_id=eq.${userId}` }, fetchCommunities)
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [fetchCommunities, userId]);

  const filteredCommunities = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return communities;
    return communities.filter((community) =>
      community.name.toLowerCase().includes(query)
      || community.description?.toLowerCase().includes(query)
    );
  }, [communities, searchQuery]);

  return (
    <div className="mx-auto w-full max-w-5xl space-y-5 px-1 pb-28 sm:space-y-7 sm:px-0 sm:pb-8">
      <div className="flex items-end justify-between gap-4">
        <div>
          <p className="mb-1 text-[11px] font-bold uppercase tracking-[0.22em] text-indigo-400">Your spaces</p>
          <h1 className="text-3xl font-black tracking-tight text-white sm:text-4xl">Communities</h1>
          <p className="mt-1 text-sm text-white/45">Your conversations, members and live rooms in one place.</p>
        </div>
        <button
          type="button"
          onClick={() => onNavigate('create-community')}
          className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-white text-black shadow-lg shadow-white/10 transition hover:scale-105 active:scale-95 sm:flex sm:w-auto sm:px-5"
          aria-label="Create community"
        >
          <Plus className="h-5 w-5" />
          <span className="hidden text-sm font-black sm:ml-2 sm:inline">Create</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-white/30" />
        <input
          type="search"
          placeholder="Search your communities"
          value={searchQuery}
          onChange={(event) => setSearchQuery(event.target.value)}
          className="h-14 w-full rounded-2xl border border-white/10 bg-white/[0.045] pl-12 pr-4 text-white outline-none transition placeholder:text-white/25 focus:border-indigo-400/50 focus:bg-white/[0.07]"
        />
      </div>

      {error ? (
        <div className="rounded-3xl border border-rose-500/20 bg-rose-500/5 p-6 text-center">
          <p className="text-sm font-semibold text-rose-200">{error}</p>
          <button type="button" onClick={fetchCommunities} className="mx-auto mt-4 flex items-center gap-2 rounded-xl bg-white/10 px-4 py-2 text-sm font-bold text-white">
            <RefreshCw className="h-4 w-4" /> Retry
          </button>
        </div>
      ) : loading ? (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          {[1, 2, 3, 4].map((item) => <div key={item} className="h-44 animate-pulse rounded-3xl bg-white/5" />)}
        </div>
      ) : filteredCommunities.length > 0 ? (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          {filteredCommunities.map((community) => {
            const owned = community.owner_id === userId;
            const privateCommunity = community.is_private || community.privacy_level === 'private';

            return (
              <motion.button
                key={community.id}
                whileHover={{ y: -3 }}
                whileTap={{ scale: 0.985 }}
                onClick={() => onNavigate(`community_${community.id}`)}
                className="group overflow-hidden rounded-[1.75rem] border border-white/10 bg-[#141414] text-left shadow-xl shadow-black/10 transition hover:border-white/20"
              >
                <div className="relative h-24 bg-gradient-to-br from-indigo-600/35 via-fuchsia-600/10 to-emerald-500/10">
                  {community.banner_url && <img src={community.banner_url} alt="" className="h-full w-full object-cover" />}
                  <div className="absolute inset-0 bg-gradient-to-t from-[#141414] to-transparent" />
                  <div className="absolute bottom-0 left-5 grid h-14 w-14 translate-y-1/2 place-items-center overflow-hidden rounded-2xl border-4 border-[#141414] bg-indigo-500 text-lg font-black text-white">
                    {community.logo_url ? <img src={community.logo_url} alt="" className="h-full w-full object-cover" /> : community.name.slice(0, 1).toUpperCase()}
                  </div>
                  <div className="absolute right-4 top-4 flex gap-2">
                    {owned && <span className="grid h-8 w-8 place-items-center rounded-xl bg-black/45 text-indigo-200 backdrop-blur"><ShieldCheck className="h-4 w-4" /></span>}
                    <span className="grid h-8 w-8 place-items-center rounded-xl bg-black/45 text-white/70 backdrop-blur">
                      {privateCommunity ? <LockKeyhole className="h-4 w-4" /> : <Globe2 className="h-4 w-4" />}
                    </span>
                  </div>
                </div>
                <div className="p-5 pt-10">
                  <div className="flex items-center gap-3">
                    <h2 className="min-w-0 flex-1 truncate text-lg font-black text-white">{community.name}</h2>
                    <ChevronRight className="h-5 w-5 text-white/20 transition group-hover:translate-x-1 group-hover:text-white" />
                  </div>
                  <p className="mt-2 line-clamp-2 min-h-10 text-sm leading-5 text-white/40">
                    {community.description || 'A new Wersee community.'}
                  </p>
                  <div className="mt-4 flex items-center gap-4 border-t border-white/5 pt-4 text-xs font-semibold text-white/40">
                    <span className="flex items-center gap-1.5"><Users className="h-3.5 w-3.5" /> {community.member_count}</span>
                    <span className="flex items-center gap-1.5"><MessageSquare className="h-3.5 w-3.5" /> {community.channel_count} channels</span>
                    {community.latest_message_at && <span className="ml-auto h-2 w-2 rounded-full bg-emerald-400" title="Recent activity" />}
                  </div>
                </div>
              </motion.button>
            );
          })}
        </div>
      ) : (
        <div className="rounded-[2rem] border border-dashed border-white/10 bg-white/[0.025] px-6 py-16 text-center">
          <div className="mx-auto mb-5 grid h-16 w-16 place-items-center rounded-2xl bg-indigo-500/10">
            <Users className="h-8 w-8 text-indigo-300" />
          </div>
          <h3 className="text-xl font-black text-white">{searchQuery ? 'Nothing found' : 'Create your first community'}</h3>
          <p className="mx-auto mt-2 max-w-sm text-sm text-white/40">
            {searchQuery ? `No community matches “${searchQuery}”.` : 'Start with ready-made channels, roles, realtime chat and a live room.'}
          </p>
          {!searchQuery && (
            <button type="button" onClick={() => onNavigate('create-community')} className="mt-6 rounded-2xl bg-white px-5 py-3 text-sm font-black text-black">
              Create community
            </button>
          )}
        </div>
      )}
    </div>
  );
};
