import React, { useCallback, useEffect, useState } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import {
  Box,
  ChevronRight,
  FileText,
  LayoutGrid,
  List,
  Package,
  Play,
  Search,
  ShoppingBag,
  X,
} from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../lib/supabase';
import { Skeleton } from '../ui/Skeleton';

interface JoinedProductsViewProps {
  onNavigate: (view: string) => void;
}

interface JoinedProduct {
  id: string;
  title: string;
  description?: string | null;
  image_url?: string | null;
  images?: string[] | null;
  type: string;
  metadata?: {
    is_all_access?: boolean;
    all_access_category?: string;
    [key: string]: unknown;
  } | null;
  seller_id?: string | null;
  purchase?: {
    id: string;
    created_at: string;
  };
  business?: {
    id: string;
    name: string;
    logo_url?: string | null;
    user_id: string;
  };
}

const productTypeLabel = (type?: string) => (type || 'product').replace(/_/g, ' ');

const ProductTypeIcon = ({ type, className = 'h-3.5 w-3.5' }: { type?: string; className?: string }) => {
  if (type === 'course') return <Play className={`${className} text-indigo-300`} />;
  if (type === 'asset_3d') return <Box className={`${className} text-sky-300`} />;
  if (type === 'digital') return <FileText className={`${className} text-emerald-300`} />;
  return <Package className={`${className} text-blue-300`} />;
};

const ProductSkeleton = ({ compact = false }: { compact?: boolean }) => (
  <div className={compact ? 'flex items-center gap-3 rounded-[1.75rem] border border-white/[0.07] bg-white/[0.025] p-3' : 'overflow-hidden rounded-[1.9rem] border border-white/[0.07] bg-white/[0.025]'}>
    <Skeleton className={compact ? 'h-16 w-16 shrink-0 rounded-[1.25rem]' : 'aspect-[16/9] w-full rounded-none'} />
    <div className={compact ? 'min-w-0 flex-1 space-y-2' : 'space-y-3 p-5'}>
      <Skeleton className="h-3 w-24 rounded-full" />
      <Skeleton className="h-5 w-2/3" />
      <Skeleton className="h-3 w-full" />
    </div>
  </div>
);

export const JoinedProductsView: React.FC<JoinedProductsViewProps> = ({ onNavigate }) => {
  const { user } = useAuth();
  const [products, setProducts] = useState<JoinedProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const prefersReducedMotion = useReducedMotion();

  const fetchJoinedProducts = useCallback(async () => {
    if (!user) {
      setProducts([]);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const { data: orders, error } = await supabase
        .from('orders')
        .select(`
          id,
          created_at,
          listing:listings (
            id,
            title,
            description,
            image_url,
            images,
            type,
            metadata,
            seller_id
          )
        `)
        .eq('buyer_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      let extractedProducts: JoinedProduct[] = (orders || [])
        .map((order: any) => order.listing ? {
          ...order.listing,
          purchase: { id: order.id, created_at: order.created_at },
        } as JoinedProduct : null)
        .filter((product): product is JoinedProduct => product !== null);

      const bundles = extractedProducts.filter((product) => product.type === 'bundle');
      const regularBundleIds = bundles
        .filter((bundle) => !bundle.metadata?.is_all_access)
        .map((bundle) => bundle.id);
      const allAccessBundles = bundles.filter((bundle) => (
        bundle.metadata?.is_all_access && bundle.metadata?.all_access_category && bundle.seller_id
      ));

      const expansionTasks: Array<Promise<JoinedProduct[]>> = [];

      if (regularBundleIds.length > 0) {
        expansionTasks.push((async () => {
          const { data, error: bundleError } = await supabase
            .from('bundle_items')
            .select(`
              listing:listings!bundle_items_product_id_fkey (
                id,
                title,
                description,
                image_url,
                images,
                type,
                seller_id
              )
            `)
            .in('bundle_id', regularBundleIds);
          if (bundleError) {
            console.error('Error fetching bundle items:', bundleError);
            return [];
          }
          return (data || [])
            .map((bundleItem: any) => bundleItem.listing as JoinedProduct | null)
            .filter((product): product is JoinedProduct => product !== null);
        })());
      }

      allAccessBundles.forEach((bundle) => {
        expansionTasks.push((async () => {
          const { data, error: allAccessError } = await supabase
            .from('listings')
            .select('id,title,description,image_url,images,type,seller_id')
            .eq('seller_id', bundle.seller_id as string)
            .eq('category', bundle.metadata?.all_access_category as string)
            .neq('type', 'bundle');
          if (allAccessError) {
            console.error('Error fetching all-access products:', allAccessError);
            return [];
          }
          return (data || []) as JoinedProduct[];
        })());
      });

      if (expansionTasks.length > 0) {
        const expandedProducts = await Promise.all(expansionTasks);
        extractedProducts = [...extractedProducts, ...expandedProducts.flat()];
      }

      const uniqueProducts = Array.from(
        new Map(extractedProducts.map((product) => [product.id, product] as const)).values(),
      ).filter((product) => product.type !== 'bundle');

      const sellerIds = [...new Set(uniqueProducts.map((product) => product.seller_id).filter((id): id is string => Boolean(id)))];
      if (sellerIds.length === 0) {
        setProducts(uniqueProducts);
        return;
      }

      const { data: businessesData, error: businessesError } = await supabase
        .from('businesses')
        .select('id,name,logo_url,user_id')
        .in('user_id', sellerIds);

      if (businessesError) {
        console.error('Error fetching product businesses:', businessesError);
        setProducts(uniqueProducts);
        return;
      }

      const businessMap = new Map((businessesData || []).map((business) => [business.user_id, business] as const));
      setProducts(uniqueProducts.map((product) => ({
        ...product,
        business: product.seller_id ? businessMap.get(product.seller_id) : undefined,
      })));
    } catch (error) {
      console.error('Error fetching joined products:', error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    void fetchJoinedProducts();
  }, [fetchJoinedProducts]);

  const normalizedSearch = searchQuery.trim().toLowerCase();
  const filteredProducts = products.filter((product) => (
    product.title.toLowerCase().includes(normalizedSearch)
    || product.business?.name.toLowerCase().includes(normalizedSearch)
  ));

  return (
    <div className="mx-auto max-w-7xl space-y-4 p-4 md:p-7">
      <header className="flex flex-col gap-4 px-1 sm:flex-row sm:items-end sm:justify-between">
        <div className="min-w-0">
          <div className="mb-2 flex flex-wrap items-center gap-2">
            <span className="inline-flex items-center gap-2 rounded-full border border-fuchsia-400/15 bg-fuchsia-400/[0.08] px-3 py-1 text-[10px] font-black uppercase tracking-[0.18em] text-fuchsia-200">
              <ShoppingBag className="h-3.5 w-3.5" /> Product library
            </span>
            <span className="rounded-full border border-white/[0.08] bg-white/[0.035] px-3 py-1 text-[10px] font-bold text-white/45">
              {products.length} {products.length === 1 ? 'product' : 'products'}
            </span>
          </div>
          <h1 className="text-2xl font-black tracking-tight text-white sm:text-3xl">My products</h1>
          <p className="mt-1 text-sm text-white/40">Everything you own, ready to open from one place.</p>
        </div>
      </header>

      <section className="flex flex-col gap-2.5 rounded-[1.8rem] border border-white/[0.07] bg-white/[0.025] p-2.5 sm:flex-row sm:items-center" aria-label="Product library controls">
        <div className="relative min-w-0 flex-1">
          <Search className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" />
          <input
            type="search"
            aria-label="Search owned products"
            placeholder="Search products or creators"
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            className="h-11 w-full rounded-full border border-white/[0.07] bg-black/25 pl-11 pr-10 text-sm text-white outline-none placeholder:text-white/25 focus:border-fuchsia-400/35 focus:bg-white/[0.035]"
          />
          {searchQuery && (
            <button type="button" onClick={() => setSearchQuery('')} className="absolute right-2 top-1/2 grid h-8 w-8 -translate-y-1/2 place-items-center rounded-full text-white/30 hover:bg-white/[0.07] hover:text-white" aria-label="Clear search">
              <X className="h-3.5 w-3.5" />
            </button>
          )}
        </div>

        <div className="grid grid-cols-2 rounded-full border border-white/[0.07] bg-black/25 p-1" role="group" aria-label="Product layout">
          <button
            type="button"
            aria-pressed={viewMode === 'grid'}
            onClick={() => setViewMode('grid')}
            className={`inline-flex h-9 items-center justify-center gap-2 rounded-full px-3.5 text-xs font-bold transition ${viewMode === 'grid' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            <LayoutGrid className="h-3.5 w-3.5" /> Grid
          </button>
          <button
            type="button"
            aria-pressed={viewMode === 'list'}
            onClick={() => setViewMode('list')}
            className={`inline-flex h-9 items-center justify-center gap-2 rounded-full px-3.5 text-xs font-bold transition ${viewMode === 'list' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            <List className="h-3.5 w-3.5" /> List
          </button>
        </div>
      </section>

      <section aria-live="polite" aria-busy={loading}>
        {loading ? (
          viewMode === 'grid' ? (
            <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
              <ProductSkeleton />
              <ProductSkeleton />
              <ProductSkeleton />
            </div>
          ) : (
            <div className="space-y-2.5">
              <ProductSkeleton compact />
              <ProductSkeleton compact />
              <ProductSkeleton compact />
            </div>
          )
        ) : products.length === 0 ? (
          <div className="rounded-[2rem] border border-dashed border-white/10 bg-white/[0.02] px-5 py-14 text-center">
            <div className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-white/[0.08] bg-white/[0.035]">
              <Package className="h-6 w-6 text-white/25" />
            </div>
            <h2 className="mt-4 text-lg font-black text-white">No products yet</h2>
            <p className="mx-auto mt-1 max-w-md text-sm leading-6 text-white/35">Products and courses you purchase will appear here with their real access status.</p>
            <button type="button" onClick={() => window.location.assign('/')} className="mt-5 inline-flex h-11 items-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black hover:bg-fuchsia-100">
              Explore store <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        ) : filteredProducts.length === 0 ? (
          <div className="rounded-[2rem] border border-dashed border-white/10 bg-white/[0.02] px-5 py-14 text-center">
            <div className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-white/[0.08] bg-white/[0.035]">
              <Search className="h-6 w-6 text-white/25" />
            </div>
            <h2 className="mt-4 text-lg font-black text-white">No matching products</h2>
            <p className="mt-1 text-sm text-white/35">Try another product or creator name.</p>
            <button type="button" onClick={() => setSearchQuery('')} className="mt-5 inline-flex h-11 items-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black hover:bg-fuchsia-100">
              <X className="h-4 w-4" /> Clear search
            </button>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {filteredProducts.map((product, index) => {
              const image = product.image_url || product.images?.[0];
              const accessLabel = product.type === 'asset_3d' ? 'View in 3D' : product.type === 'course' ? 'Continue course' : 'Open product';
              return (
                <motion.button
                  key={product.id}
                  type="button"
                  initial={prefersReducedMotion ? false : { opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: prefersReducedMotion ? 0 : Math.min(index * 0.03, 0.18) }}
                  onClick={() => onNavigate(`access_${product.id}`)}
                  className="group overflow-hidden rounded-[1.9rem] border border-white/[0.07] bg-[#101012] text-left transition hover:border-fuchsia-300/25 hover:bg-white/[0.035] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fuchsia-300/50"
                  aria-label={`Open ${product.title}`}
                >
                  <span className="relative block aspect-[16/9] overflow-hidden bg-white/[0.035]">
                    {image ? (
                      <img src={image} alt="" className="h-full w-full object-cover transition duration-500 group-hover:scale-105" referrerPolicy="no-referrer" />
                    ) : (
                      <span className="grid h-full w-full place-items-center bg-gradient-to-br from-white/[0.04] to-transparent"><Package className="h-9 w-9 text-white/15" /></span>
                    )}
                    <span className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/65 to-transparent" />
                    <span className="absolute right-3 top-3 inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-black/60 px-2.5 py-1.5 text-[9px] font-black uppercase tracking-[0.12em] text-white/70 backdrop-blur-xl">
                      <ProductTypeIcon type={product.type} /> {productTypeLabel(product.type)}
                    </span>
                  </span>

                  <span className="flex min-h-[11.5rem] flex-col p-5">
                    {product.business && (
                      <span className="mb-3 inline-flex w-fit max-w-full items-center gap-2 rounded-full border border-white/[0.07] bg-white/[0.035] py-1 pl-1 pr-2.5">
                        {product.business.logo_url ? (
                          <img src={product.business.logo_url} alt="" className="h-6 w-6 rounded-full object-cover" referrerPolicy="no-referrer" />
                        ) : (
                          <span className="grid h-6 w-6 place-items-center rounded-full bg-fuchsia-400/10 text-[9px] font-black text-fuchsia-200">{product.business.name.charAt(0)}</span>
                        )}
                        <span className="truncate text-[10px] font-bold text-white/40">{product.business.name}</span>
                      </span>
                    )}
                    <span className="line-clamp-2 text-lg font-black leading-tight text-white transition group-hover:text-fuchsia-100">{product.title}</span>
                    <span className="mt-2 line-clamp-2 text-xs leading-5 text-white/35">{product.description || 'No description provided.'}</span>
                    <span className="mt-auto flex items-center justify-between pt-4">
                      <span className="inline-flex h-9 items-center gap-2 rounded-full bg-white/[0.045] px-3 text-[10px] font-black uppercase tracking-[0.1em] text-white/50">
                        <span className="h-1.5 w-1.5 rounded-full bg-emerald-300" /> {accessLabel}
                      </span>
                      <span className="grid h-9 w-9 place-items-center rounded-full bg-white text-black transition group-hover:bg-fuchsia-100"><ChevronRight className="h-4 w-4" /></span>
                    </span>
                  </span>
                </motion.button>
              );
            })}
          </div>
        ) : (
          <div className="space-y-2.5">
            {filteredProducts.map((product, index) => {
              const image = product.image_url || product.images?.[0];
              const accessLabel = product.type === 'asset_3d' ? 'View in 3D' : product.type === 'course' ? 'Continue' : 'Open';
              return (
                <motion.button
                  key={product.id}
                  type="button"
                  initial={prefersReducedMotion ? false : { opacity: 0, x: -8 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: prefersReducedMotion ? 0 : Math.min(index * 0.025, 0.15) }}
                  onClick={() => onNavigate(`access_${product.id}`)}
                  className="group flex w-full items-center gap-3 rounded-[1.75rem] border border-white/[0.07] bg-[#101012] p-3 text-left transition hover:border-fuchsia-300/25 hover:bg-white/[0.035] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fuchsia-300/50 sm:rounded-full"
                  aria-label={`Open ${product.title}`}
                >
                  <span className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-[1.25rem] border border-white/[0.07] bg-white/[0.035] sm:rounded-full">
                    {image ? <img src={image} alt="" className="h-full w-full object-cover transition duration-500 group-hover:scale-105" referrerPolicy="no-referrer" /> : <Package className="h-6 w-6 text-white/15" />}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="flex flex-wrap items-center gap-1.5">
                      <span className="inline-flex items-center gap-1.5 rounded-full bg-white/[0.04] px-2.5 py-1 text-[9px] font-black uppercase tracking-[0.1em] text-white/40">
                        <ProductTypeIcon type={product.type} className="h-3 w-3" /> {productTypeLabel(product.type)}
                      </span>
                      {product.business && <span className="max-w-[10rem] truncate rounded-full bg-white/[0.04] px-2.5 py-1 text-[9px] font-bold text-white/30">{product.business.name}</span>}
                    </span>
                    <span className="mt-1.5 block truncate text-sm font-black text-white transition group-hover:text-fuchsia-100 sm:text-base">{product.title}</span>
                    <span className="mt-0.5 block truncate text-xs text-white/30">{product.description || 'No description provided.'}</span>
                  </span>
                  <span className="hidden h-10 shrink-0 items-center gap-2 rounded-full bg-white px-4 text-xs font-black text-black transition group-hover:bg-fuchsia-100 sm:inline-flex">
                    {accessLabel} <ChevronRight className="h-3.5 w-3.5" />
                  </span>
                  <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white/[0.05] text-white/45 sm:hidden"><ChevronRight className="h-4 w-4" /></span>
                </motion.button>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
};
