import React, { useEffect, useMemo, useState } from 'react';
import { Elements, PaymentElement, useElements, useStripe } from '@stripe/react-stripe-js';
import { loadStripe, type Stripe as StripeClient } from '@stripe/stripe-js';
import {
  AlertCircle,
  ArrowLeft,
  Building2,
  Check,
  CheckCircle2,
  ChevronDown,
  CircleDollarSign,
  Delete,
  Loader2,
  RefreshCcw,
  ShieldCheck,
  Wallet,
  X,
} from 'lucide-react';
import { invokeApiRunner, supabase } from '../../lib/supabase';
import type { PointsWalletBalance } from '../payments/PointsWalletSlider';

type BankConnection = {
  name: string;
  last4: string | null;
  country: string | null;
  currency: string | null;
};

type TopupState = {
  id: string;
  walletId: string;
  amountMinor: number;
  currency: string;
  status: string;
  failureCode?: string | null;
};

type WalletAddMoneyFlowProps = {
  wallets: PointsWalletBalance[];
  selectedWalletId: string | null;
  onSelectWallet: (walletId: string) => void;
  bank: BankConnection | null;
  bankUnavailable?: boolean;
  initialTopupId?: string | null;
  onClose: () => void;
  onConnectBank: () => void;
  onSuccess: () => void | Promise<void>;
};

const eur = new Intl.NumberFormat('nl-NL', {
  style: 'currency',
  currency: 'EUR',
  minimumFractionDigits: 2,
});

const parseAmountMinor = (value: string) => {
  const normalized = value.replace(',', '.');
  const amount = Number(normalized);
  return Number.isFinite(amount) ? Math.round(amount * 100) : 0;
};

const edgeErrorMessage = async (error: any, data: any, fallback: string) => {
  if (typeof data?.error === 'string') return data.error;
  try {
    const context = await error?.context?.json?.();
    if (typeof context?.error === 'string') return context.error;
  } catch {
    // The provider did not return a JSON error body.
  }
  return error?.message || fallback;
};

const TopupPaymentForm = ({
  clientSecret,
  topup,
  onConfirmed,
  onBack,
}: {
  clientSecret: string;
  topup: TopupState;
  onConfirmed: () => Promise<void>;
  onBack: () => void;
}) => {
  const stripe = useStripe();
  const elements = useElements();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!stripe || !elements || submitting) return;
    setSubmitting(true);
    setError(null);

    const submitResult = await elements.submit();
    if (submitResult.error) {
      setError(submitResult.error.message || 'Check your payment details.');
      setSubmitting(false);
      return;
    }

    const returnUrl = new URL(window.location.href);
    returnUrl.searchParams.set('tab', 'overview');
    returnUrl.searchParams.set('view', 'money-points');
    returnUrl.searchParams.set('wallet_topup', topup.id);

    const result = await stripe.confirmPayment({
      elements,
      clientSecret,
      confirmParams: { return_url: returnUrl.toString() },
      redirect: 'if_required',
    });

    if (result.error) {
      setError(result.error.message || 'The payment could not be completed.');
      setSubmitting(false);
      return;
    }

    await onConfirmed();
    setSubmitting(false);
  };

  return (
    <form onSubmit={submit} className="space-y-5">
      <PaymentElement
        options={{
          layout: {
            type: 'accordion',
            defaultCollapsed: false,
            radios: 'always',
            spacedAccordionItems: true,
          },
          business: { name: 'Wersee Wallet' },
        }}
      />

      {error && (
        <div className="flex items-start gap-3 rounded-2xl border border-red-400/20 bg-red-400/10 p-4 text-sm text-red-100">
          <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-red-300" />
          <p>{error}</p>
        </div>
      )}

      <div className="grid grid-cols-[auto_1fr] gap-3 pt-2">
        <button
          type="button"
          onClick={onBack}
          disabled={submitting}
          className="flex h-14 items-center justify-center rounded-2xl border border-white/10 px-5 text-sm font-bold text-white transition hover:bg-white/5 disabled:opacity-40"
        >
          Back
        </button>
        <button
          type="submit"
          disabled={!stripe || !elements || submitting}
          className="flex h-14 items-center justify-center gap-2 rounded-2xl bg-white px-5 text-sm font-black text-black transition hover:bg-white/90 disabled:opacity-40"
        >
          {submitting ? <Loader2 className="h-5 w-5 animate-spin" /> : <ShieldCheck className="h-5 w-5" />}
          {submitting ? 'Confirming…' : `Add ${eur.format(topup.amountMinor / 100)}`}
        </button>
      </div>
    </form>
  );
};

export const WalletAddMoneyFlow = ({
  wallets,
  selectedWalletId,
  onSelectWallet,
  bank,
  bankUnavailable = false,
  initialTopupId = null,
  onClose,
  onConnectBank,
  onSuccess,
}: WalletAddMoneyFlowProps) => {
  const [amountInput, setAmountInput] = useState('0');
  const [screen, setScreen] = useState<'amount' | 'payment' | 'status'>(
    initialTopupId ? 'status' : 'amount',
  );
  const [stripePromise, setStripePromise] = useState<Promise<StripeClient | null> | null>(null);
  const [clientSecret, setClientSecret] = useState<string | null>(null);
  const [topup, setTopup] = useState<TopupState | null>(
    initialTopupId
      ? { id: initialTopupId, walletId: '', amountMinor: 0, currency: 'eur', status: 'processing' }
      : null,
  );
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const selectedWallet = useMemo(
    () => wallets.find((wallet) => wallet.wallet_id === selectedWalletId) || wallets[0] || null,
    [selectedWalletId, wallets],
  );
  const amountMinor = parseAmountMinor(amountInput);
  const amountValid = amountMinor >= 100 && amountMinor <= 500000;

  useEffect(() => {
    if (!selectedWalletId && wallets[0]) onSelectWallet(wallets[0].wallet_id);
  }, [onSelectWallet, selectedWalletId, wallets]);

  const checkStatus = async (topupId: string, poll = false) => {
    setScreen('status');
    setBusy(true);
    setError(null);

    const attempts = poll ? 8 : 1;
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      const { data, error: invokeError } = await supabase.functions.invoke('wallet-add-money', {
        body: { action: 'status', topupId },
      });
      if (invokeError || data?.error) {
        setError(await edgeErrorMessage(invokeError, data, 'The wallet payment status is unavailable.'));
        setBusy(false);
        return;
      }

      const nextTopup = data?.topup as TopupState | undefined;
      if (nextTopup) setTopup(nextTopup);
      if (nextTopup?.status === 'succeeded') {
        await onSuccess();
        setBusy(false);
        return;
      }
      if (['failed', 'canceled'].includes(nextTopup?.status || '')) {
        setBusy(false);
        return;
      }
      if (attempt < attempts - 1) await new Promise((resolve) => window.setTimeout(resolve, 1400));
    }
    setBusy(false);
  };

  useEffect(() => {
    if (initialTopupId) void checkStatus(initialTopupId, true);
    // initialTopupId is intentionally handled once when returning from Stripe.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialTopupId]);

  const addKey = (key: string) => {
    setError(null);
    setAmountInput((current) => {
      if (key === 'reset') return '0';
      if (key === 'backspace') {
        const next = current.slice(0, -1);
        return next && next !== '-' ? next : '0';
      }
      if (key === ',') {
        return current.includes(',') ? current : `${current},`;
      }
      const decimals = current.split(',')[1];
      if (decimals?.length >= 2) return current;
      const next = current === '0' && !current.includes(',') ? key : `${current}${key}`;
      return parseAmountMinor(next) <= 500000 ? next : current;
    });
  };

  const startPayment = async () => {
    if (!selectedWallet || !amountValid || busy) return;
    setBusy(true);
    setError(null);

    try {
      let publishableKey = String(import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY || '').trim();
      if (!publishableKey) {
        const config = await invokeApiRunner('stripe-config', {}, 1, 800);
        publishableKey = typeof config?.publishableKey === 'string' ? config.publishableKey.trim() : '';
      }
      if (!publishableKey) throw new Error('Secure payments are temporarily unavailable.');

      const { data, error: invokeError } = await supabase.functions.invoke('wallet-add-money', {
        body: {
          action: 'create',
          walletId: selectedWallet.wallet_id,
          amountMinor,
          currency: 'eur',
        },
      });
      if (invokeError || data?.error) {
        throw new Error(await edgeErrorMessage(invokeError, data, 'The wallet payment could not start.'));
      }
      if (!data?.clientSecret || !data?.topup?.id) {
        throw new Error('The payment provider did not return a secure payment session.');
      }

      setStripePromise(loadStripe(publishableKey));
      setClientSecret(data.clientSecret);
      setTopup(data.topup as TopupState);
      setScreen('payment');
    } catch (startError) {
      setError(startError instanceof Error ? startError.message : 'The wallet payment could not start.');
    } finally {
      setBusy(false);
    }
  };

  const retry = () => {
    setClientSecret(null);
    setTopup(null);
    setError(null);
    setScreen('amount');
  };

  const statusSucceeded = topup?.status === 'succeeded';
  const statusFailed = topup?.status === 'failed' || topup?.status === 'canceled';

  return (
    <div className="fixed inset-0 z-[120] overflow-y-auto bg-[#080808] text-white">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -left-28 -top-32 h-96 w-96 rounded-full bg-orange-500/10 blur-[120px]" />
        <div className="absolute -bottom-40 right-0 h-[30rem] w-[30rem] rounded-full bg-indigo-500/10 blur-[140px]" />
      </div>

      <div className="relative mx-auto flex min-h-[100dvh] w-full max-w-6xl flex-col px-4 pb-[calc(24px+env(safe-area-inset-bottom))] pt-[calc(16px+env(safe-area-inset-top))] sm:px-6 lg:px-10">
        <header className="flex items-center justify-between gap-3">
          <button
            type="button"
            onClick={screen === 'amount' ? onClose : () => setScreen('amount')}
            className="flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] transition hover:bg-white/10"
            aria-label={screen === 'amount' ? 'Close Add Money' : 'Back to amount'}
          >
            {screen === 'amount' ? <X className="h-5 w-5" /> : <ArrowLeft className="h-5 w-5" />}
          </button>
          <div className="flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-4 py-2 text-xs font-black uppercase tracking-[0.18em] text-white/65">
            <CircleDollarSign className="h-4 w-4 text-emerald-300" />
            Add money
          </div>
          <div className="h-11 w-11" aria-hidden="true" />
        </header>

        {screen === 'amount' && (
          <main className="flex flex-1 items-center py-6 lg:py-10">
            <div className="grid w-full gap-5 lg:grid-cols-[minmax(0,1fr)_420px] lg:gap-8">
              <section className="flex min-h-[370px] flex-col rounded-[2rem] border border-white/[0.08] bg-[#111]/95 p-5 shadow-2xl sm:p-7 lg:min-h-[650px] lg:p-9">
                <div className="flex items-center justify-between gap-3">
                  {bank ? (
                    <div className="flex min-w-0 items-center gap-3">
                      <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-white text-black">
                        <Building2 className="h-5 w-5" />
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-black">{bank.name}</p>
                        <p className="text-xs text-white/35">{bank.last4 ? `•••• ${bank.last4}` : 'Connected bank'}</p>
                      </div>
                    </div>
                  ) : bankUnavailable ? (
                    <div className="flex min-w-0 items-center gap-3 text-white/55">
                      <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-amber-300/10 text-amber-200">
                        <AlertCircle className="h-5 w-5" />
                      </div>
                      <div>
                        <p className="text-sm font-black">Bank unavailable</p>
                        <p className="text-xs text-white/35">Try again later</p>
                      </div>
                    </div>
                  ) : (
                    <button type="button" onClick={onConnectBank} className="flex min-w-0 items-center gap-3 text-left">
                      <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-white/[0.07] text-white/55">
                        <Building2 className="h-5 w-5" />
                      </div>
                      <div>
                        <p className="text-sm font-black">Connect a bank</p>
                        <p className="text-xs text-white/35">For withdrawals</p>
                      </div>
                    </button>
                  )}
                  <div className="flex shrink-0 items-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-3 py-2 text-sm font-black">
                    <span className="flex h-6 w-6 items-center justify-center rounded-full bg-[#123b74] text-xs">€</span>
                    EUR
                  </div>
                </div>

                <div className="flex flex-1 flex-col items-center justify-center py-10 text-center">
                  <p className="text-[10px] font-black uppercase tracking-[0.24em] text-white/25">Amount to add</p>
                  <p className="mt-3 text-6xl font-medium tracking-[-0.07em] text-white sm:text-7xl lg:text-8xl">
                    {eur.format(amountMinor / 100)}
                  </p>
                  <p className="mt-5 rounded-full bg-white/[0.05] px-4 py-2 text-xs text-white/35">
                    Real EUR balance in your selected Wersee Wallet
                  </p>
                </div>

                <div className="grid grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-2">
                  <label className="relative min-w-0">
                    <span className="sr-only">Selected wallet</span>
                    <Wallet className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/45" />
                    <select
                      value={selectedWallet?.wallet_id || ''}
                      onChange={(event) => onSelectWallet(event.target.value)}
                      className="h-12 w-full appearance-none truncate rounded-full border border-white/10 bg-white/[0.05] pl-9 pr-9 text-sm font-bold text-white outline-none focus:border-white/25"
                    >
                      {!wallets.length && <option value="" className="bg-[#111]">No wallet available</option>}
                      {wallets.map((wallet) => (
                        <option key={wallet.wallet_id} value={wallet.wallet_id} className="bg-[#111]">
                          {wallet.name}
                        </option>
                      ))}
                    </select>
                    <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/35" />
                  </label>
                  <button
                    type="button"
                    onClick={() => addKey('reset')}
                    className="flex h-12 w-12 items-center justify-center rounded-full border border-white/10 bg-white/[0.05] text-white/70 transition hover:bg-white/10"
                    aria-label="Reset amount"
                  >
                    <RefreshCcw className="h-4 w-4" />
                  </button>
                  <div className="flex h-12 items-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-4 text-sm font-black">
                    <span className="text-white/35">€</span> EUR
                  </div>
                </div>
              </section>

              <section className="flex flex-col rounded-[2rem] border border-white/[0.08] bg-[#111]/95 p-4 shadow-2xl sm:p-5 lg:min-h-[650px]">
                <div className="grid flex-1 grid-cols-3 gap-2.5">
                  {['7', '8', '9', '4', '5', '6', '1', '2', '3', ',', '0', 'backspace'].map((key) => (
                    <button
                      key={key}
                      type="button"
                      onClick={() => addKey(key)}
                      className="flex min-h-16 items-center justify-center rounded-2xl border border-white/[0.04] bg-white/[0.07] text-2xl font-medium transition hover:bg-white/[0.11] active:scale-[0.98] lg:min-h-20 lg:text-3xl"
                      aria-label={key === 'backspace' ? 'Delete last digit' : key}
                    >
                      {key === 'backspace' ? <Delete className="h-6 w-6" /> : key}
                    </button>
                  ))}
                </div>

                {error && (
                  <div className="mt-4 flex items-start gap-3 rounded-2xl border border-red-400/20 bg-red-400/10 p-4 text-sm text-red-100">
                    <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-red-300" />
                    <p>{error}</p>
                  </div>
                )}

                {!wallets.length && (
                  <div className="mt-4 rounded-2xl border border-amber-300/20 bg-amber-300/10 p-4 text-sm text-amber-100">
                    Create a Wersee Wallet before adding money.
                  </div>
                )}

                <button
                  type="button"
                  onClick={() => void startPayment()}
                  disabled={!amountValid || !selectedWallet || busy}
                  className="mt-4 flex h-16 w-full items-center justify-center gap-2 rounded-2xl bg-white text-base font-black text-black transition hover:bg-white/90 disabled:opacity-35"
                >
                  {busy ? <Loader2 className="h-5 w-5 animate-spin" /> : <Check className="h-5 w-5" />}
                  {busy ? 'Starting secure payment…' : 'Continue'}
                </button>
                <p className="mt-3 text-center text-[11px] leading-5 text-white/25">
                  Minimum €1.00 · Maximum €5,000.00 · Payment processed by Stripe
                </p>
              </section>
            </div>
          </main>
        )}

        {screen === 'payment' && topup && clientSecret && stripePromise && (
          <main className="mx-auto flex w-full max-w-4xl flex-1 items-center py-7 lg:py-12">
            <div className="grid w-full gap-5 lg:grid-cols-[300px_minmax(0,1fr)]">
              <aside className="h-fit rounded-[2rem] border border-white/[0.08] bg-[#111] p-6">
                <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-300/10 text-emerald-300">
                  <Wallet className="h-6 w-6" />
                </div>
                <p className="mt-6 text-xs font-black uppercase tracking-[0.2em] text-white/30">Adding</p>
                <p className="mt-2 text-4xl font-black tracking-tight">{eur.format(topup.amountMinor / 100)}</p>
                <div className="mt-6 border-t border-white/[0.07] pt-5">
                  <p className="text-xs text-white/30">Selected wallet</p>
                  <p className="mt-1 font-bold">{selectedWallet?.name || 'Wersee Wallet'}</p>
                  <p className="mt-1 text-xs text-white/35">{selectedWallet?.card_label}</p>
                </div>
                <div className="mt-6 flex items-start gap-2 text-xs leading-5 text-white/35">
                  <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-emerald-300" />
                  Your balance is credited only after Stripe confirms the payment.
                </div>
              </aside>

              <section className="rounded-[2rem] border border-white/[0.08] bg-[#111] p-5 sm:p-7">
                <h1 className="text-2xl font-black tracking-tight">Choose how to pay</h1>
                <p className="mt-2 text-sm leading-6 text-white/40">
                  Available methods are supplied securely by Stripe for this EUR payment.
                </p>
                <div className="mt-7">
                  <Elements
                    stripe={stripePromise}
                    options={{
                      clientSecret,
                      appearance: {
                        theme: 'night',
                        variables: {
                          colorPrimary: '#ffffff',
                          colorBackground: '#171717',
                          colorText: '#ffffff',
                          colorDanger: '#f87171',
                          borderRadius: '16px',
                          spacingUnit: '5px',
                        },
                      },
                    }}
                  >
                    <TopupPaymentForm
                      clientSecret={clientSecret}
                      topup={topup}
                      onBack={() => setScreen('amount')}
                      onConfirmed={() => checkStatus(topup.id, true)}
                    />
                  </Elements>
                </div>
              </section>
            </div>
          </main>
        )}

        {screen === 'status' && (
          <main className="mx-auto flex w-full max-w-xl flex-1 items-center py-8">
            <section className="w-full rounded-[2.25rem] border border-white/[0.08] bg-[#111] p-7 text-center shadow-2xl sm:p-10">
              <div className={`mx-auto flex h-20 w-20 items-center justify-center rounded-full ${
                statusSucceeded
                  ? 'bg-emerald-300/10 text-emerald-300'
                  : statusFailed
                    ? 'bg-red-300/10 text-red-300'
                    : 'bg-white/[0.06] text-white/70'
              }`}>
                {statusSucceeded
                  ? <CheckCircle2 className="h-10 w-10" />
                  : statusFailed
                    ? <AlertCircle className="h-10 w-10" />
                    : <Loader2 className={`h-9 w-9 ${busy ? 'animate-spin' : ''}`} />}
              </div>
              <h1 className="mt-7 text-3xl font-black tracking-tight">
                {statusSucceeded
                  ? 'Money added'
                  : statusFailed
                    ? 'Payment not completed'
                    : 'Payment processing'}
              </h1>
              <p className="mx-auto mt-3 max-w-md text-sm leading-6 text-white/45">
                {statusSucceeded
                  ? `${eur.format(Number(topup?.amountMinor || 0) / 100)} is now available in your Wersee Wallet.`
                  : statusFailed
                    ? 'Your wallet was not credited. You can safely try again with another payment method.'
                    : 'Stripe is still confirming the payment. Your wallet will only be credited after confirmation.'}
              </p>

              {error && (
                <div className="mt-6 rounded-2xl border border-amber-300/20 bg-amber-300/10 p-4 text-sm text-amber-100">
                  {error}
                </div>
              )}

              <div className="mt-8 grid gap-3 sm:grid-cols-2">
                {(statusFailed || error) && (
                  <button type="button" onClick={retry} className="h-14 rounded-2xl bg-white font-black text-black">
                    Try again
                  </button>
                )}
                {!statusSucceeded && !statusFailed && (
                  <button
                    type="button"
                    onClick={() => topup?.id && void checkStatus(topup.id, true)}
                    disabled={busy}
                    className="flex h-14 items-center justify-center gap-2 rounded-2xl bg-white font-black text-black disabled:opacity-40"
                  >
                    <RefreshCcw className="h-4 w-4" /> Check again
                  </button>
                )}
                <button
                  type="button"
                  onClick={onClose}
                  className={`h-14 rounded-2xl border border-white/10 font-bold text-white hover:bg-white/5 ${
                    statusSucceeded ? 'sm:col-span-2' : ''
                  }`}
                >
                  Back to Wallet
                </button>
              </div>
            </section>
          </main>
        )}
      </div>
    </div>
  );
};
